#include "unistd.h"
#include <stddef.h>
#define CAP 256u
static void err(void){(void)write(2,"sed: usage sed s/OLD/NEW/[g]\n",30);}
static int find(const char*s,size_t n,const char*p,size_t m,size_t start){if(!m)return (int)start;for(size_t i=start;i+m<=n;++i){size_t j=0;while(j<m&&s[i+j]==p[j])++j;if(j==m)return (int)i;}return -1;}
static int emit(const char*line,size_t n,const char*old,size_t on,const char*newv,size_t nn,int global){size_t pos=0;for(;;){int at=find(line,n,old,on,pos);if(at<0){if(write(1,line+pos,n-pos)!=(rix_ssize_t)(n-pos))return -1;break;}if(write(1,line+pos,(size_t)at-pos)!=(rix_ssize_t)((size_t)at-pos)||write(1,newv,nn)!=(rix_ssize_t)nn)return -1;pos=(size_t)at+on;if(!global){if(write(1,line+pos,n-pos)!=(rix_ssize_t)(n-pos))return -1;break;}}return write(1,"\n",1)==1?0:-1;}
int program_main(int argc,char**argv,char**envp){(void)envp;if(argc<2||argv[1][0]!='s'||argv[1][1]!='/'){err();return 2;}char*spec=argv[1];size_t a=2,old_start=a;while(spec[a]&&spec[a]!='/')++a;if(!spec[a]){err();return 2;}size_t on=a-old_start,ns=a+1,b=ns;while(spec[b]&&spec[b]!='/')++b;if(!spec[b]){err();return 2;}size_t nn=b-ns;int global=spec[b+1]=='g',fd=0;if(argc>2){fd=openat(-100,argv[2],0,0);if(fd<0)return 1;}char line[CAP];size_t used=0;for(;;){char buf[64];rix_ssize_t count=read(fd,buf,sizeof(buf));if(count<0){if(fd>2)(void)close(fd);return 1;}if(count==0){int rc=used?emit(line,used,spec+old_start,on,spec+ns,nn,global):0;if(fd>2)(void)close(fd);return rc;}for(size_t i=0;i<(size_t)count;++i){if(buf[i]=='\n'){if(emit(line,used,spec+old_start,on,spec+ns,nn,global)!=0){if(fd>2)(void)close(fd);return 1;}used=0;}else if(used+1u<CAP)line[used++]=buf[i];else{if(fd>2)(void)close(fd);return 1;}}}}
